/* ==================================================================================
   0. CONSTANTS, PRNG, SMALL HELPERS
   ================================================================================== */
const VERSION = "ashfall-1";
const WIN_TURN = 60, WIN_POP = 12;
const STORM_EVERY = 6, CARAVAN_EVERY = 6, CARAVAN_STAY = 2;

/* mulberry32 - state lives in the game object so saves round-trip exactly.
   Math.random() is never called anywhere in this file. */
function mulberry32(a){
  return function(){
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
/* Draw from a state object (so we can serialize the cursor). */
function rnd(G){ G.rngState = (G.rngState + 0x6D2B79F5) | 0;
  let a = G.rngState, t = Math.imul(a ^ (a >>> 15), 1 | a);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
function rint(G,lo,hi){ return lo + Math.floor(rnd(G) * (hi - lo + 1)); }
function pick(G,arr){ return arr[Math.floor(rnd(G) * arr.length)]; }
const clamp = (v,lo,hi) => v < lo ? lo : v > hi ? hi : v;
const r1 = v => Math.round(v * 10) / 10;
const r2 = v => Math.round(v * 100) / 100;

/* FNV-1a over canonical JSON (keys sorted) -> stable state hash. */
function canon(v){
  if (v === null || typeof v !== "object") return JSON.stringify(v);
  if (Array.isArray(v)) return "[" + v.map(canon).join(",") + "]";
  const k = Object.keys(v).sort();
  return "{" + k.map(x => JSON.stringify(x) + ":" + canon(v[x])).join(",") + "}";
}
function hashStr(s){
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++){ h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return ("00000000" + h.toString(16)).slice(-8);
}
function stateHash(G){ return hashStr(canon(G)); }

