// Temporary verification harness (not part of the deliverable).
// Extracts the engine from game.html, drops the DOM-dependent sections,
// then runs the in-game test suite and benchmark under node.
const fs = require("fs");
const vm = require("vm");

const html = fs.readFileSync(
  "/home/zmhel/gitrepos/learn-ai/eval01/runs/.gen-work/t25/game.html", "utf8");

const a = html.indexOf("<script>");
const b = html.lastIndexOf("</script>");
if (a < 0 || b < 0) throw new Error("no script block");
const js = html.slice(a + 8, b);

function bannerStart(marker) {
  const i = js.indexOf(marker);
  if (i < 0) throw new Error("marker not found: " + marker);
  const j = js.lastIndexOf("/* ==", i);
  if (j < 0) throw new Error("banner not found for: " + marker);
  return j;
}
const s13 = bannerStart("   13. UI");
const s14 = bannerStart("   14. HEADLESS GREEDY POLICY");
const s16 = bannerStart("   16. WIRING");

const code =
  js.slice(0, s13) +
  "\nlet G = null;\n" +
  js.slice(s14, s16) +
  "\nG = newGame(1337);\n" +
  "console.log(runTests());\n" +
  "console.log('');\n" +
  "console.log(runBench());\n";

const ctx = { console: console };
vm.createContext(ctx);
const t0 = Date.now();
vm.runInContext(code, ctx, { filename: "ashfall-engine.js" });
console.log("\nharness wall time: " + (Date.now() - t0) + " ms");
